/* Reminder screens read current vehicle/customer data directly, without duplicating it. */
let amcSelectedVehicle='';
function latestKnownServiceDate(b){let dates=[b.lastServiceDate,...db.jobs.filter(j=>j.bike===b.id&&['Completed','Delivered'].includes(j.status)).map(j=>j.date)].filter(validAmcDate);return dates.sort().at(-1)||''}
function existingVehicleAmcRow(b){let c=find('customers',b.customer),a=effectiveVehicleAmc(b);return {...a,id:b.id,contractKey:'bikes',contractId:b.id,customer:b.customer,vehicleNumbers:b.number,name:c?.name||'Customer not linked',mobile:c?.mobile||'',make:b.brand||'',model:b.model||'',lastServiceDate:latestKnownServiceDate(b),nextServiceDate:b.nextServiceDate||'',amcSource:'Vehicle AMC'}}
function existingVehicleAmcRows(){return db.bikes.map(existingVehicleAmcRow)}
function selectedVehicleAmcRow(){return existingVehicleAmcRows().find(e=>e.id===amcSelectedVehicle)||existingVehicleAmcRows()[0]||null}
function existingAmcRowFilter(e){let d=amcExpiryDays(e);return amcReminderFilter==='all'||amcReminderFilter==='no-amc'&&!e.amcType||amcReminderFilter==='due'&&d!==null&&d<=0||amcReminderFilter==='expired'&&d!==null&&d<0||amcReminderFilter==='today'&&d===0||amcReminderFilter==='upcoming'&&d!==null&&d>0&&d<=Number(amcReminderWindow)||amcReminderFilter==='incomplete'&&e.amcType&&d===null}
function amcExistingDetailsMarkup(e){if(!e)return '<p>No vehicles found. Add a vehicle in Vehicle Master first.</p>';return `<div class="amcAutofillDetails"><strong>${esc(e.vehicleNumbers)} · ${esc([e.make,e.model].filter(Boolean).join(' '))}</strong><p>Customer: ${esc(e.name)} · Mobile: ${esc(e.mobile||'Not entered')}</p><p>AMC: ${esc(e.amcType||'No AMC')} · Validity: ${esc(e.amcStart||'Not set')} to ${esc(e.amcExpiry||'Not set')}</p><p>Last service: ${esc(e.lastServiceDate||'Not recorded')} · Next service: ${esc(e.nextServiceDate||'Not scheduled')}</p></div>`}
amcActionPanel=function(){let entries=existingVehicleAmcRows(),selected=selectedVehicleAmcRow();return `<section class="amcActionPanel"><h3>Vehicle AMC — Existing Details</h3><label class="field"><span>Select Existing Vehicle</span><select id="amcActionContract">${entries.length?opts(entries.map(e=>({value:'bikes|'+e.id,label:e.vehicleNumbers+' — '+e.name+' — '+(e.amcType||'No AMC')})),selected?'bikes|'+selected.id:''):'<option value="">No vehicles found</option>'}</select></label><div id="amcAutofillDetails">${amcExistingDetailsMarkup(selected)}</div><div class="amcActionButtons"><button class="btn" type="button" id="amcActionAdd">Add / Edit Selected Vehicle AMC</button>${[['whatsapp','WhatsApp Reminder'],['edit','Edit AMC'],['renew','Renew AMC'],['sent','Record Sent'],['history','History']].map(([action,label])=>`<button class="btn ${action==='whatsapp'?'success':'secondary'}" type="button" data-amc-toolbar-action="${action}">${action==='whatsapp'?whatsappIcon():''}${label}</button>`).join('')}</div></section>`};
amcRemindersPage=function(){let all=existingVehicleAmcRows(),contracts=all.filter(e=>e.amcType),rows=all.filter(matches).filter(existingAmcRowFilter);return amcActionPanel()+pendingVehicleAmcMarkup()+summary([['VEHICLES WITH AMC',contracts.length],['EXPIRED AMC',contracts.filter(e=>amcExpiryDays(e)!==null&&amcExpiryDays(e)<0).length],['EXPIRING IN 30 DAYS',contracts.filter(e=>amcExpiryDays(e)!==null&&amcExpiryDays(e)>=0&&amcExpiryDays(e)<=30).length],['VEHICLES WITHOUT AMC',all.length-contracts.length]])+'<div class="notice">Existing vehicle/customer details are filled automatically. Missing plan or expiry dates must be entered; they are not guessed. Last service includes completed/delivered job history.</div>'+toolbar('',`<select id="amcReminderFilter" aria-label="AMC reminder filter">${opts([{value:'all',label:'All Existing Vehicles'},{value:'no-amc',label:'Vehicles Without AMC'},{value:'due',label:'Expired & Today'},{value:'expired',label:'Expired'},{value:'today',label:'Expires Today'},{value:'upcoming',label:'Expiring Soon'},{value:'incomplete',label:'Missing Expiry'}],amcReminderFilter)}</select><select id="amcReminderWindow" aria-label="AMC expiry window">${opts([{value:'7',label:'Next 7 Days'},{value:'30',label:'Next 30 Days'},{value:'90',label:'Next 90 Days'}],amcReminderWindow)}</select>`)+table(['Vehicle Number','Make / Model','Customer','Mobile','AMC Plan','Valid From','Valid Until','AMC Status','Last Service','Next Service','Actions'],rows.map(e=>[esc(e.vehicleNumbers),esc([e.make,e.model].filter(Boolean).join(' ')),esc(e.name),esc(e.mobile||'—'),esc(e.amcType||'No AMC'),esc(e.amcStart||'—'),esc(e.amcExpiry||'—'),badge(customerAmcStatus(e)),esc(e.lastServiceDate||'—'),esc(e.nextServiceDate||'—'),`<div class="rowactions"><button class="btn small editButton" type="button" data-existing-amc-edit="${esc(e.id)}">${icon('edit')} ${e.amcType?'Edit AMC':'Add AMC'}</button><button class="btn small success" type="button" data-existing-amc-message="${esc(e.id)}" ${!e.amcType||amcExpiryDays(e)===null?'disabled':''}>${whatsappIcon()} Reminder</button><button class="btn small secondary" type="button" data-existing-amc-renew="${esc(e.id)}" ${e.amcType?'':'disabled'}>Renew AMC</button><button class="btn small secondary" type="button" data-existing-amc-sent="${esc(e.id)}" ${e.amcType&&amcExpiryDays(e)!==null?'':'disabled'}>Record Sent</button></div>`]))};
const actionBeforeExistingAmc=performAmcAction;
performAmcAction=function(action,value){let [key,id]=String(value||'').split('|');if(action==='edit'&&key==='bikes'&&find('bikes',id))return editRecord('bikes',id);return actionBeforeExistingAmc(action,value)};
function bindExistingAmcActions(){let select=$('#amcActionContract');if(!select)return;function sync(){let id=select.value.split('|')[1],e=existingVehicleAmcRows().find(r=>r.id===id);amcSelectedVehicle=id;$('#amcAutofillDetails').innerHTML=amcExistingDetailsMarkup(e);for(let button of $$('[data-amc-toolbar-action]'))button.disabled=!e||button.dataset.amcToolbarAction!=='edit'&&(!e.amcType||amcExpiryDays(e)===null);if($('#amcActionAdd'))$('#amcActionAdd').disabled=!e}select.onchange=sync;sync();$('#amcActionAdd').onclick=()=>{let id=select.value.split('|')[1];if(id)editRecord('bikes',id)};for(let button of $$('[data-existing-amc-edit]'))button.onclick=()=>editRecord('bikes',button.dataset.existingAmcEdit);for(let [attribute,action]of [['existingAmcMessage','whatsapp'],['existingAmcRenew','renew'],['existingAmcSent','sent']]){let selector='[data-'+attribute.replace(/[A-Z]/g,m=>'-'+m.toLowerCase())+']';for(let button of $$(selector))button.onclick=()=>performAmcAction(action,'bikes|'+button.dataset[attribute])}}
const renderBeforeExistingAmc=render;
render=function(){renderBeforeExistingAmc();if(page==='amc-reminders'||page==='service-reminders'&&reminderView==='amc')bindExistingAmcActions()};
const editBeforeServiceHistoryAutofill=editRecord;
editRecord=function(key,id,initial){editBeforeServiceHistoryAutofill(key,id,initial);if(key!=='bikes'||!id)return;let b=find('bikes',id),form=$('#recordForm'),last=form?.querySelector('[name="lastServiceDate"]');if(last&&!last.value)last.value=latestKnownServiceDate(b);if(form){let info=document.createElement('div');info.className='notice';info.textContent='Existing vehicle: '+b.number+' · '+name('customers',b.customer)+' · '+(find('customers',b.customer)?.mobile||'No mobile');form.querySelector('.formbody')?.prepend(info)}};
const scheduleBeforeServiceHistoryAutofill=openServiceSchedule;
openServiceSchedule=function(id){scheduleBeforeServiceHistoryAutofill(id);let form=$('#serviceScheduleForm');if(!form)return;let select=form.querySelector('[name="vehicle"]');let fill=()=>{let b=find('bikes',select.value),last=form.querySelector('[name="lastServiceDate"]');if(b&&last&&!last.value)last.value=latestKnownServiceDate(b)};select.addEventListener('change',fill);fill()};
render();
